<html lang="<?= \App\Core\Localization::current() ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= \App\Core\t('Forgot your password?') ?> — c0m.me</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><?php require __DIR__ . '/partials/language-switcher.php'; ?><main class="auth-wrap"><a class="brand" href="/">c0m.me</a><section class="auth-card"><span class="eyebrow"><?= \App\Core\t("ACCOUNT RECOVERY") ?></span><h1><?= \App\Core\t("Forgot your password?") ?></h1><p><?= \App\Core\t("Enter the email address associated with your account. If it matches an active account, we'll send a reset link.") ?></p><?php if (!empty($error)): ?><div class="alert"><?= htmlspecialchars(\App\Core\t($error), ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?><form method="post" action="/forgot-password"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token(), ENT_QUOTES, 'UTF-8') ?>"><label><?= \App\Core\t("Email address") ?></label><input type="email" name="email" maxlength="190" autocomplete="email" required><button class="button full" type="submit"><?= \App\Core\t("Send reset link") ?></button></form><small><a href="/login"><?= \App\Core\t("Back to sign in") ?></a></small></section></main></body></html>
